package api

import ("encoding/json"; "net/http"; "strings"; "go.mau.fi/whatsmeow/internal/database"; "go.mau.fi/whatsmeow/internal/email")

func alvoRevendaEmail(r *http.Request, cli *database.Cliente)(*database.Revendedor,error){if cli.Papel==database.PapelRevendedor{return database.DB.BuscarRevendedorPorID(cli.RevendedorID)};return database.DB.BuscarRevendedorPorDominio(r.Host)}
func HandlerEmailRevenda(w http.ResponseWriter,r *http.Request){cli:=obterUsuarioAutenticado(r);if cli==nil||cli.ViaChaveAPI||(cli.Papel!=database.PapelRevendedor&&cli.Papel!=database.PapelSuperAdmin){responderErro(w,403,"Apenas revendedores podem configurar e-mail");return};rev,err:=alvoRevendaEmail(r,cli);if err!=nil||rev==nil{responderErro(w,404,"Revenda não localizada");return};if r.Method==http.MethodGet{c,e:=database.DB.BuscarConfiguracaoEmailRevenda(rev.ID);if e!=nil{responderSucesso(w,"Resend ainda não configurado",map[string]interface{}{"configurado":false});return};c.APIKey="";responderSucesso(w,"Configuração carregada",map[string]interface{}{"configurado":true,"configuracao":c});return};var b struct{APIKey string `json:"api_key"`;Dominio string `json:"dominio"`;Remetente string `json:"remetente"`;NomeRemetente string `json:"nome_remetente"`};if decodificarJSONLimitado(w,r,limiteBodyJSONPadrao,&b)!=nil||strings.TrimSpace(b.APIKey)==""||strings.TrimSpace(b.Remetente)==""{responderErro(w,400,"API Key e remetente são obrigatórios");return};c:=&database.ConfiguracaoEmailRevenda{RevendedorID:rev.ID,APIKey:b.APIKey,Dominio:strings.TrimSpace(b.Dominio),Remetente:strings.TrimSpace(b.Remetente),NomeRemetente:strings.TrimSpace(b.NomeRemetente),Ativo:true};if err:=database.DB.SalvarConfiguracaoEmailRevenda(c);err!=nil{responderErro(w,500,"Erro ao salvar Resend: "+err.Error());return};c.APIKey="";responderSucesso(w,"Resend configurado para a revenda",c)}
func HandlerTestarEmailRevenda(w http.ResponseWriter,r *http.Request){cli:=obterUsuarioAutenticado(r);if cli==nil||cli.Papel==database.PapelCliente{responderErro(w,403,"Sem permissão");return};rev,err:=alvoRevendaEmail(r,cli);if err!=nil||rev==nil{responderErro(w,404,"Revenda não localizada");return};c,err:=database.DB.BuscarConfiguracaoEmailRevenda(rev.ID);if err!=nil{responderErro(w,400,"Configure o Resend primeiro");return};var b struct{Destinatario string `json:"destinatario"`};_=json.NewDecoder(r.Body).Decode(&b);if strings.TrimSpace(b.Destinatario)==""{b.Destinatario=cli.Email};if err:=(email.Cliente{APIKey:c.APIKey,From:c.Remetente,FromName:c.NomeRemetente}).Enviar(b.Destinatario,"Teste de e-mail — "+rev.NomeEmpresa,"<p>O Resend foi configurado com sucesso.</p>");err!=nil{responderErro(w,502,err.Error());return};c.Verificado=true;_=database.DB.SalvarConfiguracaoEmailRevenda(c);responderSucesso(w,"E-mail de teste enviado",nil)}
func HandlerOnboarding(w http.ResponseWriter,r *http.Request){cli:=obterUsuarioAutenticado(r);if cli==nil||cli.ViaChaveAPI{responderErro(w,401,"Sessão inválida");return};if r.Method==http.MethodGet{d,e:=database.DB.BuscarOnboarding(cli.ID);if e!=nil{d=map[string]interface{}{ "usuario_id":cli.ID,"papel":cli.Papel,"etapa_atual":"conta","concluido":false,"dados":"{}" }};responderSucesso(w,"Onboarding carregado",d);return};var b struct{Etapa string `json:"etapa"`;Dados map[string]interface{} `json:"dados"`;Concluido bool `json:"concluido"`};if decodificarJSONLimitado(w,r,limiteBodyJSONPadrao,&b)!=nil||strings.TrimSpace(b.Etapa)==""{responderErro(w,400,"Etapa obrigatória");return};raw,_:=json.Marshal(b.Dados);if err:=database.DB.SalvarEtapaOnboarding(cli.ID,cli.Papel,b.Etapa,string(raw),b.Concluido);err!=nil{responderErro(w,500,"Erro ao salvar onboarding");return};responderSucesso(w,"Onboarding atualizado",nil)}
